const crypto = require("crypto");
const out = [];
const log = (...a) => out.push(a.map((x) => (typeof x === "string" ? x : JSON.stringify(x))).join(" "));
const t = (name, fn) => { try { log(name, fn()); } catch (e) { log(name, "THROWS", e.code || "", String(e.message).split("\n")[0].slice(0, 60)); } };
for (const alg of ["md5", "sha1", "sha224", "sha256", "sha384", "sha512"]) t("hash " + alg, () => crypto.createHash(alg).update("hello").update(Buffer.from(" world")).digest("hex"));
t("hash base64", () => crypto.createHash("sha256").update("x").digest("base64"));
t("hash buffer", () => crypto.createHash("sha1").update("x").digest().length);
t("hash twice", () => { const h = crypto.createHash("sha1").update("x"); h.digest(); return h.digest(); });
t("hash copy", () => { const h = crypto.createHash("sha256").update("a"); const c = h.copy(); return [h.update("b").digest("hex").slice(0, 8), c.digest("hex").slice(0, 8)]; });
t("hash unknown", () => crypto.createHash("nope"));
t("hash()", () => crypto.hash ? crypto.hash("sha1", "abc") : "n/a");
t("hmac", () => crypto.createHmac("sha256", "key").update("data").digest("hex"));
t("hmac sha512 buf key", () => crypto.createHmac("sha512", Buffer.from([1, 2, 3])).update("d").digest("base64"));
t("pbkdf2", () => crypto.pbkdf2Sync("password", "salt", 1000, 32, "sha256").toString("hex"));
t("pbkdf2 sha1", () => crypto.pbkdf2Sync("pw", "s", 1, 20, "sha1").toString("hex"));
t("hkdf", () => Buffer.from(crypto.hkdfSync("sha256", "key", "salt", "info", 32)).toString("hex"));
t("scrypt", () => crypto.scryptSync("password", "salt", 32, { N: 1024, r: 8, p: 1 }).toString("hex"));
const key = Buffer.alloc(32, 1), iv16 = Buffer.alloc(16, 2), iv12 = Buffer.alloc(12, 3);
for (const alg of ["aes-256-cbc", "aes-128-cbc", "aes-256-ctr"]) t("cipher " + alg, () => { const k = key.subarray(0, alg.includes("128") ? 16 : 32); const c = crypto.createCipheriv(alg, k, iv16); const enc = Buffer.concat([c.update("The quick brown fox jumps"), c.final()]); const d = crypto.createDecipheriv(alg, k, iv16); return [enc.toString("hex"), Buffer.concat([d.update(enc), d.final()]).toString()]; });
t("cipher ecb", () => { const c = crypto.createCipheriv("aes-128-ecb", key.subarray(0, 16), null); return Buffer.concat([c.update("abcdefghijklmnop"), c.final()]).toString("hex"); });
t("cipher gcm", () => { const c = crypto.createCipheriv("aes-256-gcm", key, iv12); c.setAAD(Buffer.from("aad")); const enc = Buffer.concat([c.update("secret message"), c.final()]); const tag = c.getAuthTag(); const d = crypto.createDecipheriv("aes-256-gcm", key, iv12); d.setAAD(Buffer.from("aad")); d.setAuthTag(tag); return [enc.toString("hex"), tag.toString("hex"), Buffer.concat([d.update(enc), d.final()]).toString()]; });
t("gcm bad tag", () => { const c = crypto.createCipheriv("aes-256-gcm", key, iv12); const enc = Buffer.concat([c.update("x"), c.final()]); const d = crypto.createDecipheriv("aes-256-gcm", key, iv12); d.setAuthTag(Buffer.alloc(16)); d.update(enc); return d.final(); });
t("chacha", () => { const c = crypto.createCipheriv("chacha20-poly1305", key, iv12, { authTagLength: 16 }); const enc = Buffer.concat([c.update("hi there"), c.final()]); return [enc.toString("hex"), c.getAuthTag().toString("hex")]; });
t("cbc bad decrypt", () => { const d = crypto.createDecipheriv("aes-128-cbc", key.subarray(0, 16), iv16); d.update(Buffer.alloc(16, 9)); return d.final(); });
t("cbc no padding", () => { const c = crypto.createCipheriv("aes-128-cbc", key.subarray(0, 16), iv16); c.setAutoPadding(false); return Buffer.concat([c.update(Buffer.alloc(16, 5)), c.final()]).toString("hex"); });
t("bad key length", () => crypto.createCipheriv("aes-256-cbc", Buffer.alloc(5), iv16));
t("bad iv", () => crypto.createCipheriv("aes-256-cbc", key, Buffer.alloc(3)));
t("random", () => [crypto.randomBytes(8).length, crypto.randomUUID().length, crypto.randomInt(10) < 10, crypto.randomInt(5, 6), typeof crypto.getRandomValues(new Uint8Array(4))[0], crypto.randomFillSync(Buffer.alloc(4)).length]);
t("timingSafeEqual", () => [crypto.timingSafeEqual(Buffer.from("a"), Buffer.from("a")), crypto.timingSafeEqual(Buffer.from("a"), Buffer.from("b"))]);
t("timingSafeEqual len", () => crypto.timingSafeEqual(Buffer.from("a"), Buffer.from("ab")));
t("lists", () => [crypto.getHashes().includes("sha256"), crypto.getCiphers().includes("aes-256-gcm")]);
t("webcrypto", () => [typeof globalThis.crypto.getRandomValues, typeof crypto.webcrypto.subtle.digest, typeof globalThis.crypto.randomUUID()]);
// RSA / EC sign and verify with keys generated by Node for the fixture
const fs = require("fs"), path = require("path");
const rsaPriv = fs.readFileSync(path.join(__dirname, "test-key.pem"), "utf8"), cert = fs.readFileSync(path.join(__dirname, "test-cert.pem"), "utf8");
t("rsa sign verify", () => { const sig = crypto.createSign("RSA-SHA256").update("payload").sign(rsaPriv); return [sig.length, crypto.createVerify("RSA-SHA256").update("payload").verify(cert, sig), crypto.createVerify("RSA-SHA256").update("tampered").verify(cert, sig)]; });
t("rsa deterministic", () => crypto.sign("sha256", Buffer.from("m"), rsaPriv).toString("hex").slice(0, 32));
t("rsa sha1 base64", () => crypto.createSign("sha1").update("z").sign(rsaPriv, "base64").length);
(async () => {
  const subtle = crypto.webcrypto.subtle;
  log("subtle digest", Buffer.from(await subtle.digest("SHA-256", Buffer.from("abc"))).toString("hex"));
  const k = await subtle.importKey("raw", Buffer.from("secret"), { name: "HMAC", hash: "SHA-256" }, false, ["sign", "verify"]);
  const sig = await subtle.sign("HMAC", k, Buffer.from("data"));
  log("subtle hmac", Buffer.from(sig).toString("hex"), await subtle.verify("HMAC", k, sig, Buffer.from("data")));
  console.log(out.join("\n"));
})();
